package com.team2052.lib.commands;

import java.util.ArrayList;
import java.util.List;

import org.wpilib.command3.Command;
import org.wpilib.command3.Mechanism;
import org.wpilib.command3.Scheduler;

import lombok.Getter;
import lombok.Setter;

public abstract class CommandBase {

  private List<Mechanism> requirements = new ArrayList<>();
  @Getter @Setter private String name = "Unnamed Command";

  /**
   * Creates and returns the {@link Command} generated by this interface. Does NOT run the {@link
   * Command}, only returns it. Can be used to initialize it for large commands that may require
   * significant runtime to generate.
   *
   * @return the created {@link Command}
   */
  public Command create() {
    return Command.requiring(requirements).executing(coroutine -> {
      initialize();
      while (!isFinished()) {
        execute();
        coroutine.yield();
      }
      end();
    }).whenCanceled(() -> end()).named(name);
  };

  /** Creates and then schedules the command. Calls {@link CommandBase#create()} for the command. */
  public void schedule() {
    Scheduler.getDefault().schedule(create());
  }

  /** Initializes the command as soon as it is scheduled. */
  public void initialize() {}

  /** Called repeatedly while the command is scheduled. */
  public void execute() {}

  /**
   * Returns whether the command should finish. If this returns true, the command will end and {@link CommandBase#end()} will be called.
   * @return true if the command should finish, false otherwise
   */
  public boolean isFinished() {
    return false;
  }

  /** Called when the command ends. */
  public void end() {}

  /**
   * Adds a requirement to the command. The command will not run if any of its requirements are
   * already in use by another command.
   *
   * @param mechanism the mechanism to add as a requirement
   */
  public void addRequirement(Mechanism mechanism) {
    requirements.add(mechanism);
  }

  /**
   * Adds multiple requirements to the command. The command will not run if any of its requirements
   * are already in use by another command.
   *
   * @param mechanisms the mechanisms to add as requirements
   */
  public void addRequirements(Mechanism... mechanisms) {
    for (Mechanism mechanism : mechanisms) {
      addRequirement(mechanism);
    }
  }

}
